const H = params.height;
const s = H / 2.2;
const primary = { preset: 'metal', color: params.color, metalness: 0.55, roughness: 0.34 };
const trim = { preset: 'metal', color: '#d9d3bf', metalness: 0.72, roughness: 0.26 };
const dark = { preset: 'metal', color: '#303944', metalness: 0.7, roughness: 0.3 };
const rubber = { preset: 'rubber', color: '#20262c', roughness: 0.82 };
const glow = { preset: 'emissive', color: params.eyeColor, emissive: params.eyeColor, emissiveIntensity: 3.5, roughness: 0.18 };
const red = { preset: 'emissive', color: '#ff604f', emissive: '#ff3020', emissiveIntensity: 1.8 };
const torsoY = 1.15 * s;
api.add(api.box(0.82*s, 0.72*s, 0.48*s).translate(0, torsoY, 0), primary);
api.add(api.box(0.72*s, 0.055*s, 0.40*s).translate(0, 0.775*s, 0), trim);
api.add(api.box(0.58*s, 0.42*s, 0.045*s).translate(0, 1.15*s, 0.263*s), dark);
api.add(api.box(0.48*s, 0.055*s, 0.025*s).translate(0, 1.28*s, 0.292*s), trim);
for (let i = 0; i < 4; i++) {
  const x = (-0.18 + i * 0.12) * s;
  const mat = i === 0 ? red : (i === 1 ? glow : trim);
  api.add(api.sphere(0.035*s, 1).scale(1, 1, 0.45).translate(x, 1.10*s, 0.294*s), mat);
}
for (let i = 0; i < 3; i++) api.add(api.box(0.34*s, 0.025*s, 0.018*s).translate(0, (0.99-i*0.055)*s, 0.295*s), trim);
api.add(api.box(0.44*s, 0.26*s, 0.035*s).translate(0, 1.18*s, -0.258*s), dark);
for (let i = 0; i < 4; i++) api.add(api.box(0.28*s, 0.018*s, 0.018*s).translate(0, (1.27-i*0.06)*s, -0.281*s), trim);
api.add(api.cylinder(0.15*s, 0.15*s, 0.13*s, 12).translate(0, 1.57*s, 0), dark);
api.add(api.cylinder(0.34*s, 0.34*s, 0.08*s, 16).translate(0, 1.65*s, 0), trim);
api.add(api.cylinder(0.31*s, 0.31*s, 0.34*s, 16).translate(0, 1.84*s, 0), primary);
api.add(api.sphere(0.31*s, 2).scale(1, 0.45, 1).translate(0, 2.01*s, 0), primary);
api.add(api.box(0.46*s, 0.16*s, 0.035*s).translate(0, 1.87*s, 0.305*s), dark);
for (let i = -1; i <= 1; i += 2) {
  const x = i * 0.14*s;
  api.add(api.sphere(0.072*s, 2).scale(1, 0.78, 0.38).translate(x, 1.89*s, 0.337*s), glow);
  api.add(api.torus(0.075*s, 0.018*s).translate(x, 1.89*s, 0.326*s), trim);
}
api.add(api.box(0.14*s, 0.022*s, 0.018*s).translate(0, 1.76*s, 0.333*s), trim);
api.add(api.box(0.22*s, 0.11*s, 0.035*s).translate(0, 1.87*s, -0.326*s), dark);
api.add(api.cylinder(0.025*s, 0.025*s, 0.25*s, 8).translate(0, 2.22*s, 0), trim);
api.add(api.sphere(0.07*s, 2).translate(0, 2.37*s, 0), red);
for (let side = -1; side <= 1; side += 2) {
  const x = side * 0.53*s;
  api.add(api.sphere(0.13*s, 1).translate(side*0.45*s, 1.36*s, 0), dark);
  api.add(api.cylinder(0.105*s, 0.105*s, 0.38*s, 10).rotate(0, 0, side*8).translate(x, 1.18*s, 0), primary);
  api.add(api.sphere(0.12*s, 1).translate(side*0.56*s, 0.98*s, 0), trim);
  api.add(api.cylinder(0.09*s, 0.09*s, 0.30*s, 10).rotate(0, 0, -side*5).translate(side*0.575*s, 0.82*s, 0), primary);
  api.add(api.sphere(0.13*s, 1).scale(0.8, 1, 0.75).translate(side*0.59*s, 0.62*s, 0), dark);
}
for (let side = -1; side <= 1; side += 2) {
  const x = side * 0.22*s;
  api.add(api.cylinder(0.13*s, 0.13*s, 0.30*s, 10).translate(x, 0.61*s, 0), primary);
  api.add(api.sphere(0.14*s, 1).translate(x, 0.43*s, 0), dark);
  api.add(api.cylinder(0.115*s, 0.13*s, 0.27*s, 10).translate(x, 0.275*s, 0), trim);
  api.add(api.box(0.31*s, 0.12*s, 0.43*s).translate(x, 0.06*s, 0.07*s), primary);
  api.add(api.box(0.32*s, 0.035*s, 0.44*s).translate(x, 0.0175*s, 0.07*s), rubber);
}
api.collider({ kind: 'box', halfExtents: [0.41*s, 0.36*s, 0.24*s], offset: [0, torsoY, 0] });
api.collider({ kind: 'sphere', radius: 0.33*s, offset: [0, 1.87*s, 0] });
api.collider({ kind: 'box', halfExtents: [0.38*s, 0.38*s, 0.28*s], offset: [0, 0.38*s, 0] });
api.collider({ kind: 'box', halfExtents: [0.66*s, 0.42*s, 0.18*s], offset: [0, 1.04*s, 0] });
return api.build();
